import sqlite3
for db in ("source","target"):
    con = sqlite3.connect("file:databases/%s.db?mode=ro" % db, uri=True)
    print("===", db)
    for (name, sql) in con.execute("SELECT name, sql FROM sqlite_master WHERE type IN ('table','view') ORDER BY name"):
        try:
            n = con.execute('SELECT COUNT(*) FROM "%s"' % name).fetchone()[0]
        except Exception as e:
            n = "err: %s" % e
        print("  %-28s %s" % (name, n))
    con.close()
PY"}

