{"command":"cd /testbed/migration-recon && python - <<'PY'
import sqlite3, json
def count(db, t):
    c = sqlite3.connect("file:databases/%s.db?mode=ro" % db, uri=True)
    try: return int(c.execute('SELECT COUNT(*) FROM "%s"' % t).fetchone()[0])
    finally: c.close()
scope = json.load(open("config/scope.json"))["scope"]
out = {}
for t in scope:
    s, g = count("source", t), count("target", t)
    sa = count("source", "orders_archive") if t == "orders" else 0
    ga = count("target", "orders_archive") if t == "orders" else 0
    out[t] = dict(phys_s=s, phys_t=g, rec_s=s+sa, rec_t=g+ga, equal=(s+sa == g+ga))
print(json.dumps(out, indent=1))
print("matched:", all(v["equal"] for v in out.values()))
PY"}

